class Solution { private fun dijkstra(start:Int,graph:Array<MutableList<LongArray>>):LongArray{val distance=LongArray(graph.size){Long.MAX_VALUE};distance[start]=0;val queue=java.util.PriorityQueue<LongArray>(compareBy{it[0]});queue.add(longArrayOf(0,start.toLong()));while(queue.isNotEmpty()){val state=queue.remove();val node=state[1].toInt();if(state[0]!=distance[node])continue;for(edge in graph[node])if(state[0]+edge[1]<distance[edge[0].toInt()]){distance[edge[0].toInt()]=state[0]+edge[1];queue.add(longArrayOf(distance[edge[0].toInt()],edge[0]))}};return distance};fun minimumWeight(n:Int,edges:Array<IntArray>,src1:Int,src2:Int,dest:Int):Long{val graph=Array(n){mutableListOf<LongArray>()};val reverse=Array(n){mutableListOf<LongArray>()};for(edge in edges){graph[edge[0]].add(longArrayOf(edge[1].toLong(),edge[2].toLong()));reverse[edge[1]].add(longArrayOf(edge[0].toLong(),edge[2].toLong()))};val first=dijkstra(src1,graph);val second=dijkstra(src2,graph);val suffix=dijkstra(dest,reverse);var answer=Long.MAX_VALUE;for(i in 0 until n)if(first[i]!=Long.MAX_VALUE&&second[i]!=Long.MAX_VALUE&&suffix[i]!=Long.MAX_VALUE)answer=minOf(answer,first[i]+second[i]+suffix[i]);return if(answer==Long.MAX_VALUE)-1 else answer} }
